INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(114758, 'ruRU', '', 'Я бы не поверил, что это возможно, если бы не увидел это своими глазами. Браво!', 24330),
(114816, 'ruRU', '', 'Что ж, это объясняет распевания, доносящиеся из его шатра в любой час ночи. И запах серы.', 24330),
(114845, 'ruRU', '', 'Я могу обеспечить нам доступ в Пурпурную Цитадель, где мы сможем сражаться с Хаккаром, не тревожась о побочном ущербе.', 24330),
(114850, 'ruRU', '', 'Мемориал нашего отца совсем рядом, за углом. Уверена, ты найдёшь Анарис где-то поблизости.', 24330),
(114861, 'ruRU', '', 'Старайся не засматриваться слишком долго. Для высших слоёв нашего общества это место едва ли отвлекает внимание.', 24330),
(114863, 'ruRU', '', 'Я добыл для тебя паланкин. Постарайся выглядеть величественно — это помогает поддерживать иллюзию.', 24330),
(114864, 'ruRU', '', 'Женщину, которую ты ищешь, зовут Марго. Она проявила интерес к нашему делу.', 24330),
(114867, 'ruRU', '', '<Малефика пристально наблюдает за другими друидами, пока твоё присутствие не отвлекает её.>$b$bТише, $c. Я слушаю.$b$b<Она снова переводит внимание на находящихся рядом друидов.>', 24330),
(114868, 'ruRU', '', 'Ах ты, мерзкая тварь — я ещё не закончила здесь. Умри!', 24330),
(114871, 'ruRU', '', 'Ну и ну, это было забавно. Нам стоит повторить это как-нибудь.', 24330),
(114894, 'ruRU', '', 'Библиотека Чертогов Хранителя не уступает библиотеке Луносвета даже в её нынешнем беспорядке. Я прослежу, чтобы магистры поддержали наши усилия здесь.', 24330),
(114895, 'ruRU', '', 'Это место хранит огромный запас знаний, $n! Я читал увлекательную историю Совета Тирисфаля. Знал ли ты, что Мерил и Алоди на самом деле создали Кузницу Хранителей?', 24330),
(114896, 'ruRU', '', 'Вы слышали! Приготовиться!', 24330),
(114898, 'ruRU', '', 'А ты смелый, знаешь. Думаю, лучше мне остаться внутри, пока здесь не станет чуть безопаснее.', 24330),
(114909, 'ruRU', '', 'Не стойте просто так, ожидая смерти. В атаку. Развернуть разрушителей!', 24330),
(114911, 'ruRU', '', 'Ты сияющий пример силы новой Тирисгарды! За нашего новейшего архимага, $n!', 24330),
(114917, 'ruRU', '', 'Лучше тебе двигаться, пока меня не выставили отсюда навсегда.', 24330),
(114926, 'ruRU', '', 'Кто-то выглядит жаждущим!', 24330),
(114927, 'ruRU', '', 'Похоже, тебе не помешала бы помощь, Ильза.', 24330),
(114943, 'ruRU', '', 'Пора в путь. Следуй за мной!', 24330),
(114944, 'ruRU', '', 'Коготь-Клинок был потерян так давно, что многие таурены никогда даже не видели его. Старейшины до сих пор рассказывают истории о том, как наши величайшие охотники владели этим копьём, защищая нашу землю.', 24330),
(114945, 'ruRU', '', 'Эти герои убивали ужасных монстров и отбивали бесчисленных захватчиков. Дорро Крутогорье был последним, кто владел им. Его конец настал от когтей осквернённого ночного саблезуба, что охотился на наши деревни.', 24330),
(114947, 'ruRU', '', 'Мы называли этого зверя Дакарром. Некогда благородное создание, доведённое до безумия помешанным мистиком-врайкулом. Дорро отбил его, а затем выследил зверя до самого Штормхейма. Он никогда не вернулся, и Коготь-Клинок больше никто не видел.', 24330),
(114948, 'ruRU', '', 'Я надеюсь, что однажды наше племя обретёт мир.', 24330),
(114949, 'ruRU', '', 'Незримый Путь здесь всегда желанный гость.', 24330),
(114955, 'ruRU', '', 'Наслаждаешься виноградником?', 24330),
(114956, 'ruRU', '', 'Благодарю, $n.', 24330),
(114959, 'ruRU', '', 'Помню, я видел что-то подобное прежде. Но где...', 24330),
(114960, 'ruRU', '', 'Ах! Виноградники!', 24330),
(114961, 'ruRU', '', 'Мы едем вместе.', 24330),
(114963, 'ruRU', '', 'Думаю, тебе понравится вид, $p. Идём!', 24330),
(114964, 'ruRU', '', 'Могу я помочь тебе?', 24330),
(114965, 'ruRU', '', 'Прошу, не стесняйся осмотреться.', 24330),
(114970, 'ruRU', '', 'Хорошо, Верховный лорд. Я дам точный отчёт о нашей армии и наших операциях.', 24330),
(114971, 'ruRU', '', 'Я слышал слухи... они казались слишком хорошими, чтобы быть правдой.\n\nПотерпи со мной — нам нужно действовать осторожно, чтобы не вызвать подозрений. Они... не слишком добры к нам.', 24330),
(114972, 'ruRU', '', 'Марго бросает взгляд по сторонам, молча оценивая обстановку.', 24330),
(114973, 'ruRU', '', 'Экскурсия? Конечно! Я покажу тебе территорию сама.', 24330),
(114975, 'ruRU', '', 'Каждый день я узнаю больше о Свете и его предназначении в этом мире. И всё же я ещё так далёк от истины.', 24330),
(114977, 'ruRU', '', 'Конечно, Верховный лорд. Я скажу, что думаю. Путь света праведен и справедлив. Какими бы ни были наши средства, пусть они остаются добродетельными.', 24330),
(114978, 'ruRU', '', 'Двор, который ты только что покинул, открыт для посетителей. Начиная с этого места, тебя должен сопровождать кто-то из моего персонала.', 24330);
